using System;
using Microsoft.Build.Logging.StructuredLogger;

var logFile = args[0];
var build = BinaryLog.ReadBuild(logFile);

Console.WriteLine("=== ALL ERRORS ===");
build.VisitAllChildren<Error>(error => {
    Console.WriteLine($"[ERROR] {error.File}({error.LineNumber},{error.ColumnNumber}): {error.Code}: {error.Text}");
    var proj = error.GetNearestParent<Project>();
    Console.WriteLine($"  Project: {proj?.Name}");
    Console.WriteLine();
});

Console.WriteLine("=== PROJECT BUILD RESULTS ===");
build.VisitAllChildren<Project>(proj => {
    var errors = new System.Collections.Generic.List<string>();
    proj.VisitAllChildren<Error>(e => errors.Add(e.Code + ": " + e.Text));
    Console.WriteLine($"  {proj.Name} errors={errors.Count}");
});

// Try to get source file content from the binlog
Console.WriteLine("\n=== COMPILER COMMAND LINES ===");
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var proj = task.GetNearestParent<Project>();
        Console.WriteLine($"  Project: {proj?.Name}");
        var cmdLine = task.CommandLineArguments;
        if (cmdLine != null) {
            // Just show the sources part
            foreach (var line in cmdLine.Split('\n')) {
                if (line.Contains(".cs") || line.Contains("reference") || line.Contains("package"))
                    Console.WriteLine($"    {line.Trim()}");
            }
        }
        Console.WriteLine();
    }
});
EOF
